css:
:root {
  --primary: #56c273;
  --primary-hover: #3fa45d;
  --bg: #0a1f14;
  --bg-alt: #123322;
  --text: #e8f6ee;
  --text-secondary: #b5d8c1;
  --card-bg: rgba(14, 39, 24, 0.78);
  --border: rgba(86, 194, 115, 0.35);
  --success: #8ee4af;
  --warning: #f0c674;
  --error: #ff8e72;
}

body {
  background: linear-gradient(145deg, #0a1f14 0%, #123322 45%, #0a1f14 100%);
  color: var(--text);
  font-variant-ligatures: contextual;
  background-image: radial-gradient(circle at 20% 20%, rgba(86, 194, 115, 0.12), transparent 36%),
                    radial-gradient(circle at 80% 0%, rgba(240, 198, 116, 0.15), transparent 30%),
                    radial-gradient(circle at 50% 70%, rgba(142, 228, 175, 0.14), transparent 36%);
}

.header {
  background: linear-gradient(90deg, rgba(86, 194, 115, 0.3), rgba(142, 228, 175, 0.2));
  border-bottom: 1px solid rgba(86, 194, 115, 0.4);
  box-shadow: 0 10px 26px rgba(86, 194, 115, 0.18);
}

.brand {
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: linear-gradient(90deg, #8ee4af, #f0c674);
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  text-shadow: 0 0 14px rgba(86, 194, 115, 0.45);
}

.board {
  background: linear-gradient(180deg, rgba(142, 228, 175, 0.08), rgba(10, 31, 20, 0.9));
  backdrop-filter: blur(2px);
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 18px;
  box-shadow: 0 10px 26px rgba(10, 31, 20, 0.65), 0 0 0 1px rgba(142, 228, 175, 0.08);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.card:hover {
  transform: translateY(-3px);
  border-color: rgba(142, 228, 175, 0.8);
  box-shadow: 0 16px 36px rgba(86, 194, 115, 0.26);
}

.card .tag, .tag {
  background: linear-gradient(135deg, #56c273, #8ee4af);
  color: #0a1f14;
  border: none;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

button, .button, .cta {
  background: linear-gradient(135deg, #8ee4af 0%, #f0c674 100%);
  color: #0a1f14;
  border-radius: 14px;
  border: none;
  box-shadow: 0 10px 28px rgba(240, 198, 116, 0.25);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

button:hover, .button:hover, .cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 36px rgba(142, 228, 175, 0.35);
}

input, textarea {
  background: rgba(10, 31, 20, 0.7);
  border: 1px solid rgba(86, 194, 115, 0.45);
  color: var(--text);
  border-radius: 12px;
}
